function getTranslation(key, lang = 'en') {
  const l = (lang || 'en').toLowerCase().slice(0, 2);
  const dict = PATIENT_I18N[l] || PATIENT_I18N.en;
  return dict[key] || PATIENT_I18N.en[key] || key;
}

