function translateClinicalSpeech(text, targetLang = 'en') {
  if (!text) return '';
  const lang = (targetLang || 'en').toLowerCase().slice(0, 2);
  if (lang === 'en') return text;
  if (lang === 'ta' && /[\u0B80-\u0BFF]/.test(text)) return text;
  if (lang === 'hi' && /[\u0900-\u097F]/.test(text)) return text;

  const trimmed = text.trim();
  if (EXACT_CLINICAL_MAP[lang] && EXACT_CLINICAL_MAP[lang][trimmed]) {
    return EXACT_CLINICAL_MAP[lang][trimmed];
  }

  // Greeting template pattern
  const greetingMatch = trimmed.match(/^Hello\s+([^,]+),\s*as\s+you\s+are\s+managing\s+an\s+acute\s+high\s+fever\s+of\s+([^\s]+)\s+along\s+with\s+dehydration\s+and\s+fatigue,\s*this\s+personalized\s+recovery\s+plan\s+is\s+designed\s+to\s+help\s+you\s+rest,\s*rehydrate,\s*and\s+heal\s+safely\./i);
  if (greetingMatch) {
    const ptName = greetingMatch[1];
    const feverVal = greetingMatch[2];
    if (lang === 'ta') {
      return `வணக்கம் ${ptName}, உங்களுக்கு ${feverVal} தீவிர காய்ச்சல், நீரிழப்பு மற்றும் சோர்வு உள்ளதால், நீங்கள் பாதுகாப்பாக ஓய்வெடுக்கவும், நீரேற்றம் பெறவும், குணமடையவும் இந்த தனிப்பயனாக்கப்பட்ட மீட்புத் திட்டம் வடிவமைக்கப்பட்டுள்ளது.`;
    }
    if (lang === 'hi') {
      return `नमस्ते ${ptName}, चूंकि आप ${feverVal} के तेज बुखार के साथ निर्जलीकरण और थकान का सामना कर रहे हैं, यह व्यक्तिगत रिकवरी योजना आपको सुरक्षित रूप से आराम करने, पुनर्जलीकरण और ठीक होने में मदद करने के लिए बनाई गई है।`;
    }
  }

  let translated = text;
  const rules = CLINICAL_SPEECH_MAP[lang] || [];
  for (const [regex, replacement] of rules) {
    translated = translated.replace(regex, replacement);
  }

  // Common section headings fallback
  if (lang === 'ta') {
    translated = translated
      .replace(/^Diet & Nutrition:\s*/i, 'உணவு மற்றும் ஊட்டச்சத்து: ')
      .replace(/^Activity & Rest:\s*/i, 'உடற்பயிற்சி மற்றும் ஓய்வு: ')
      .replace(/^Hygiene & Wound Care:\s*/i, 'சுகாதாரம் மற்றும் பராமரிப்பு: ')
      .replace(/^Medication Routine:\s*/i, 'மருந்து வழக்கம்: ')
      .replace(/Drink warm or boiled water regularly throughout the day/gi, 'நாள் முழுவதும் சீரான இடைவெளியில் வெதுவெதுப்பான அல்லது காய்ச்சிய நீரைக் குடிக்கவும்')
      .replace(/Strictly avoid heavy, hard-to-digest meats/gi, 'கனமான இறைச்சிகளை கண்டிப்பாகத் தவிர்க்கவும்')
      .replace(/Prioritize plenty of restorative sleep/gi, 'ஆழ்ந்த தூக்கத்திற்கு முன்னுரிமை அளியுங்கள்')
      .replace(/Take all your prescribed medications/gi, 'பரிந்துரைக்கப்பட்ட அனைத்து மருந்துகளையும் எடுத்துக் கொள்ளுங்கள்')
      .replace(/Record every dose in your medication intake tracker/gi, 'ஒவ்வொரு மருந்தையும் டிராக்கரில் பதிவு செய்யவும்')
      .replace(/complete your daily check-in/gi, 'தினசரி செக்-இன் முடிக்கவும்');
  } else if (lang === 'hi') {
    translated = translated
      .replace(/^Diet & Nutrition:\s*/i, 'आहार और पोषण: ')
      .replace(/^Activity & Rest:\s*/i, 'गतिविधि और आराम: ')
      .replace(/^Hygiene & Wound Care:\s*/i, 'स्वच्छता और देखभाल: ')
      .replace(/^Medication Routine:\s*/i, 'दवा की दिनचर्या: ')
      .replace(/Drink warm or boiled water regularly throughout the day/gi, 'दिन भर नियमित रूप से गुनगुना या उबला हुआ पानी पिएं')
      .replace(/Strictly avoid heavy, hard-to-digest meats/gi, 'भारी मांसाहार से पूरी तरह परहेज करें')
      .replace(/Prioritize plenty of restorative sleep/gi, 'अच्छी नींद को प्राथमिकता दें')
      .replace(/Take all your prescribed medications/gi, 'अपनी सभी निर्धारित दवाएं लें')
      .replace(/Record every dose in your medication intake tracker/gi, 'प्रत्येक खुराक को इनटेक ट्रैकर में दर्ज करें')
      .replace(/complete your daily check-in/gi, 'अपना दैनिक चेक-इन पूरा करें');
  }

  return translated;
}

async function api(path, opts = {}) {
  const s = getSession();
  const headers = { ...(opts.headers || {}) };
  if (s?.token) headers.Authorization = `Bearer ${s.token}`;
  const r = await fetch(API + path, { ...opts, headers });
  if (!r.ok) {
    let m = 'Request failed';
    try { const j = await r.json(); m = j.detail || m; } catch {}

    // Global 401 Session Expiration Interceptor:
    // If the token is invalid or expired, gracefully log out and prompt re-authentication
    if (r.status === 401 && !path.includes('/login') && !path.includes('/forgot-password') && !path.includes('/register')) {
      if (typeof window !== 'undefined') {
        saveSession(null);
        window.dispatchEvent(new CustomEvent('recovera_session_expired', {
          detail: { message: m || 'Your session has expired. Please log in again to continue.' }
        }));
      }
    }

    throw new Error(m);
  }
  return r.headers.get('content-type')?.includes('application/json') ? r.json() : r.blob();
}

/* ===========================================================
   UTILITY COMPONENTS
   =========================================================== */
function Spinner({ size = 18 }) {
  return <div className="spinner" style={{ width: size, height: size }} />;
}

function Alert({ type = 'error', children, onClose }) {
  const cls = { error: 'alert-error', success: 'alert-success', warn: 'alert-warn', info: 'alert-info' };
  const icons = { error: <AlertCircle size={16} />, success: <CheckCircle2 size={16} />, warn: <AlertTriangle size={16} />, info: <Bell size={16} /> };
  return (
    <div className={`alert ${cls[type]}`}>
      {icons[type]}
      <span style={{ flex: 1, fontSize: 13 }}>{children}</span>
      {onClose && <button onClick={onClose} style={{ opacity: 0.6, display: 'grid', placeItems: 'center' }}><X size={14} /></button>}
    </div>
  );
}

function Badge({ status, children }) {
  const cls = ['approved','active','online','taken','published','green'].includes(status) ? 'badge-green'
    : ['pending','waiting','draft','away','amber'].includes(status) ? 'badge-amber'
    : ['rejected','cancelled','missed','expired','busy','red'].includes(status) ? 'badge-red'
    : ['scheduled','under_review','needs_review','blue'].includes(status) ? 'badge-blue'
    : ['completed','violet'].includes(status) ? 'badge-violet'
    : 'badge-muted';
  return <span className={`badge ${cls}`}>{children || status}</span>;
}

function StatusDot({ status }) {
  const cls = status === 'online' ? 'online pulse' : status === 'busy' ? 'busy pulse' : 'away';
  return <span className={`status-dot ${cls}`} />;
}

function Empty({ icon: Icon = Users, title = 'Nothing here', desc = '' }) {
  return (
    <div className="empty">
      <div className="empty-icon"><Icon size={24} /></div>
      <div className="empty-title">{title}</div>
      {desc && <p className="empty-desc">{desc}</p>}
    </div>
  );
}

function Modal({ open, onClose, title, children, size = '', footer }) {
  if (!open) return null;
  const modalContent = (
    <div className="modal-backdrop" onClick={onClose}>
      <motion.div
        className={`modal ${size === 'xl' ? 'modal-xl' : size === 'lg' ? 'modal-lg' : size === 'sm' ? 'modal-sm' : size === 'md' ? 'modal-md' : ''}`}
        onClick={e => e.stopPropagation()}
        initial={{ opacity: 0, scale: 0.95, y: 16 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 12 }}
        transition={{ type: 'spring', damping: 26, stiffness: 320 }}
      >
        <div className="modal-head">
          <div className="modal-title">{title}</div>
          <button className="icon-btn" onClick={onClose}><X size={17} /></button>
        </div>
        {children}
        {footer && <div className="modal-footer">{footer}</div>}
      </motion.div>
    </div>
  );

  return typeof document !== 'undefined' ? createPortal(modalContent, document.body) : modalContent;
}

/* ===========================================================
   ADVANCED VISUAL ANALYTICS COMPONENTS
   =========================================================== */

function MicroSparkline({ data = [2, 4, 3, 6, 7, 5, 8], color = 'var(--p)', width = 64, height = 22, delta = '+12%' }) {
  if (!data || data.length < 2) return null;
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const step = width / (data.length - 1);
  const points = data.map((v, i) => {
    const x = i * step;
    const y = height - ((v - min) / range) * (height - 4) - 2;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');

  const isUp = (data[data.length - 1] >= data[0]);

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
      <svg width={width} height={height} className="sparkline-svg">
        <polyline
          fill="none"
          stroke={color}
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          points={points}
        />
      </svg>
      {delta && (
        <span className={`stat-delta-chip ${isUp ? 'stat-delta-up' : 'stat-delta-down'}`}>
          {delta}
        </span>
      )}
    </div>
  );
}

function RadialMetricGauge({
  value = 75,
  max = 100,
  size = 120,
  strokeWidth = 9,
  color = 'var(--p)',
  label = 'Clinical Score',
  sublabel = 'Optimal Range',
  prefix = '',
  suffix = '%'
}) {
  const radius = (size - strokeWidth * 2) / 2;
  const circumference = 2 * Math.PI * radius;
  const pct = Math.min(100, Math.max(0, (value / max) * 100));
  const strokeDashoffset = circumference - (pct / 100) * circumference;

  return (
    <div className="radial-gauge-card">
      <div className="radial-gauge-wrap" style={{ width: size, height: size }}>
        <svg width={size} height={size} className="radial-gauge-svg">
          <circle
            className="radial-bg-track"
            cx={size / 2}
            cy={size / 2}
            r={radius}
            strokeWidth={strokeWidth}
          />
          <circle
            className="radial-progress-bar"
            cx={size / 2}
            cy={size / 2}
            r={radius}
            strokeWidth={strokeWidth}
            stroke={color}
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            style={{ transition: 'stroke-dashoffset 1s ease' }}
          />
        </svg>
        <div className="radial-gauge-content">
          <span className="radial-gauge-val" style={{ color }}>{prefix}{value}{suffix}</span>
          {sublabel && <span className="radial-gauge-label">{sublabel}</span>}
        </div>
      </div>
      {label && <div className="radial-gauge-caption">{label}</div>}
    </div>
  );
}

function SplineAreaChart({
  data = [],
  series1 = { name: 'Encounters Scheduled', color: 'var(--p)', max: 10 },
  series2 = { name: 'Completed Encounters', color: '#38bdf8', max: 10 },
  height = 180,
  emptyMessage = "No encounter activity recorded in this timeframe."
}) {
  const [hoveredIdx, setHoveredIdx] = useState(null);
  const id1 = useMemo(() => 'grad1_' + Math.random().toString(36).substr(2, 5), []);
  const id2 = useMemo(() => 'grad2_' + Math.random().toString(36).substr(2, 5), []);

  const paddingX = 36;
  const paddingY = 24;
  const svgWidth = 500;
  const chartW = svgWidth - paddingX * 2;
  const chartH = height - paddingY * 2;

  const hasActivity = useMemo(() => {
    return Array.isArray(data) && data.some(d => (d.v1 || 0) > 0 || (d.v2 || 0) > 0);
  }, [data]);

  const max1 = series1?.max || 10;
  const max2 = series2?.max || 10;

  if (!data || data.length === 0) {
    return (
      <div
        className="chart-empty-container"
        style={{ height, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: 'var(--text-muted)', fontSize: 12, padding: 16, textAlign: 'center' }}
        role="region"
        aria-label={emptyMessage}
      >
        <Calendar size={22} style={{ marginBottom: 6, opacity: 0.6 }} />
        <span>{emptyMessage}</span>
      </div>
    );
  }

  const getPoints = (key, maxVal) => {
    return data.map((d, i) => {
      const x = paddingX + (i / Math.max(1, data.length - 1)) * chartW;
      const y = paddingY + chartH - (Math.min(maxVal, Math.max(0, d[key] || 0)) / maxVal) * chartH;
      return { x, y, val: d[key] || 0 };
    });
  };

  const pts1 = getPoints('v1', max1);
  const pts2 = series2 ? getPoints('v2', max2) : [];

  const makeSplinePath = (pts) => {
    if (pts.length < 2) return '';
    let path = `M ${pts[0].x} ${pts[0].y}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[i === 0 ? 0 : i - 1];
      const p1 = pts[i];
      const p2 = pts[i + 1];
      const p3 = pts[i + 2 < pts.length ? i + 2 : i + 1];
      const cp1x = p1.x + (p2.x - p0.x) / 6;
      const cp1y = p1.y + (p2.y - p0.y) / 6;
      const cp2x = p2.x - (p3.x - p1.x) / 6;
      const cp2y = p2.y - (p3.y - p1.y) / 6;
      path += ` C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)}, ${cp2x.toFixed(1)} ${cp2y.toFixed(1)}, ${p2.x.toFixed(1)} ${p2.y.toFixed(1)}`;
    }
    return path;
  };

  const line1 = makeSplinePath(pts1);
  const area1 = line1 && pts1.length > 0 ? `${line1} L ${pts1[pts1.length - 1].x} ${paddingY + chartH} L ${pts1[0].x} ${paddingY + chartH} Z` : '';

  const line2 = series2 ? makeSplinePath(pts2) : '';
  const area2 = line2 && pts2.length > 0 ? `${line2} L ${pts2[pts2.length - 1].x} ${paddingY + chartH} L ${pts2[0].x} ${paddingY + chartH} Z` : '';

  return (
    <div style={{ width: '100%' }} role="region" aria-label={`${series1.name} timeline chart`}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12, marginBottom: 8, fontSize: 11, flexWrap: 'wrap' }}>
        {!hasActivity && (
          <span style={{ fontSize: 10, color: 'var(--text-muted)', background: 'var(--surface2)', padding: '2px 8px', borderRadius: 4, border: '1px solid var(--border)' }}>
            ● Zero recorded activity in this period
          </span>
        )}
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 16, marginLeft: 'auto' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <span style={{ width: 10, height: 10, borderRadius: '50%', background: series1.color }} />
            <span style={{ color: 'var(--text)', fontWeight: 600 }}>{series1.name}</span>
          </div>
          {series2 && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              <span style={{ width: 10, height: 10, borderRadius: '50%', background: series2.color }} />
              <span style={{ color: 'var(--text)', fontWeight: 600 }}>{series2.name}</span>
            </div>
          )}
        </div>
      </div>

      <div style={{ position: 'relative', width: '100%', overflow: 'hidden' }}>
        <svg viewBox={`0 0 ${svgWidth} ${height}`} style={{ width: '100%', height, overflow: 'visible' }} aria-hidden="true">
          <defs>
            <linearGradient id={id1} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={series1.color} stopOpacity="0.32" />
              <stop offset="100%" stopColor={series1.color} stopOpacity="0.0" />
            </linearGradient>
            {series2 && (
              <linearGradient id={id2} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={series2.color} stopOpacity="0.32" />
                <stop offset="100%" stopColor={series2.color} stopOpacity="0.0" />
              </linearGradient>
            )}
          </defs>

          {[0, 0.33, 0.66, 1].map((pct, idx) => {
            const y = paddingY + chartH * pct;
            return (
              <line key={idx} x1={paddingX} y1={y} x2={svgWidth - paddingX} y2={y} className="spline-gridline" />
            );
          })}

          {area2 && <path d={area2} fill={`url(#${id2})`} />}
          {area1 && <path d={area1} fill={`url(#${id1})`} />}

          {line2 && <path d={line2} fill="none" stroke={series2.color} strokeWidth="2.5" strokeLinecap="round" />}
          {line1 && <path d={line1} fill="none" stroke={series1.color} strokeWidth="2.5" strokeLinecap="round" />}

          {pts1.map((p, i) => (
            <g key={'p1_' + i} onMouseEnter={() => setHoveredIdx(i)} onMouseLeave={() => setHoveredIdx(null)}>
              <circle
                cx={p.x}
                cy={p.y}
                r={hoveredIdx === i ? 6 : 3.5}
                fill="var(--surface)"
                stroke={series1.color}
                strokeWidth="2.5"
                className="spline-point-dot"
              />
              {(hoveredIdx === i || (data.length <= 7 || (data.length <= 14 ? i % 2 === 0 : data.length <= 24 ? i % 4 === 0 : i % 5 === 0) || i === data.length - 1)) && (
                <text
                  x={p.x}
                  y={height - 6}
                  textAnchor="middle"
                  className="spline-axis-label"
                  style={{ fontWeight: hoveredIdx === i ? 700 : 400 }}
                >
                  {data[i]?.label}
                </text>
              )}
            </g>
          ))}

          {pts2.map((p, i) => (
            <circle
              key={'p2_' + i}
              cx={p.x}
              cy={p.y}
              r={hoveredIdx === i ? 6 : 3.5}
              fill="var(--surface)"
              stroke={series2.color}
              strokeWidth="2.5"
              className="spline-point-dot"
              onMouseEnter={() => setHoveredIdx(i)}
              onMouseLeave={() => setHoveredIdx(null)}
            />
          ))}

          {hoveredIdx !== null && pts1[hoveredIdx] && (
            <g>
              <line
                x1={pts1[hoveredIdx].x}
                y1={paddingY}
                x2={pts1[hoveredIdx].x}
                y2={paddingY + chartH}
                stroke="var(--border2)"
                strokeDasharray="3 3"
              />
            </g>
          )}
        </svg>

        {hoveredIdx !== null && data[hoveredIdx] && (
          <div
            style={{
              position: 'absolute',
              top: 8,
              left: Math.min(85, Math.max(15, (hoveredIdx / Math.max(1, data.length - 1)) * 100)) + '%',
              transform: 'translateX(-50%)',
              background: 'var(--surface2, #0d1b26)',
              border: '1px solid var(--border)',
              borderRadius: 6,
              padding: '6px 10px',
              fontSize: 11,
              whiteSpace: 'nowrap',
              boxShadow: '0 4px 14px rgba(0,0,0,0.4)',
              pointerEvents: 'none',
              zIndex: 10
            }}
          >
            <div style={{ fontWeight: 700, color: 'var(--text)' }}>{data[hoveredIdx].label}</div>
            <div style={{ color: series1.color }}>{series1.name}: <b>{data[hoveredIdx].v1 ?? 0}</b></div>
            {series2 && <div style={{ color: series2.color }}>{series2.name}: <b>{data[hoveredIdx].v2 ?? 0}</b></div>}
          </div>
        )}
      </div>
    </div>
  );
}

function InteractiveDonutChart({
  data = [],
  title = 'Encounter Breakdown',
  centerLabel = 'Total'
}) {
  const [hovered, setHovered] = useState(null);
  const rawTotal = data.reduce((acc, d) => acc + (d.count || 0), 0);
  const total = rawTotal > 0 ? rawTotal : 1;
  const size = 130;
  const strokeWidth = 14;
  const radius = (size - strokeWidth * 2) / 2;
  const circumference = 2 * Math.PI * radius;

  let accumulatedPercent = 0;

  return (
    <div className="donut-chart-container" role="region" aria-label={title}>
      <div className="donut-svg-wrap" style={{ width: size, height: size }}>
        <svg width={size} height={size} style={{ transform: 'rotate(-90deg)', overflow: 'visible' }} aria-hidden="true">
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            stroke="var(--surface3)"
            strokeWidth={strokeWidth}
          />
          {rawTotal > 0 && data.map((seg, i) => {
            const count = seg.count || 0;
            const pct = count / total;
            const strokeDasharray = `${pct * circumference} ${circumference}`;
            const strokeDashoffset = -accumulatedPercent * circumference;
            accumulatedPercent += pct;
            const isHover = hovered === i;

            return (
              <circle
                key={i}
                cx={size / 2}
                cy={size / 2}
                r={radius}
                fill="none"
                stroke={seg.color}
                strokeWidth={isHover ? strokeWidth + 3 : strokeWidth}
                strokeDasharray={strokeDasharray}
                strokeDashoffset={strokeDashoffset}
                style={{ transition: 'stroke-width 0.2s ease, opacity 0.2s ease', cursor: 'pointer' }}
                opacity={hovered === null || isHover ? 1 : 0.4}
                onMouseEnter={() => setHovered(i)}
                onMouseLeave={() => setHovered(null)}
              />
            );
          })}
        </svg>

        <div className="donut-center-metric">
          <div className="value">{hovered !== null ? (data[hovered].count || 0) : rawTotal}</div>
          <div className="label">{hovered !== null ? data[hovered].label.slice(0, 10) : centerLabel}</div>
        </div>
      </div>

      <div className="donut-legend-list">
        {data.length === 0 ? (
          <div style={{ fontSize: 11, color: 'var(--text-muted)', textAlign: 'center', padding: '10px 0' }}>
            No encounter distribution recorded.
          </div>
        ) : (
          data.map((seg, i) => {
            const count = seg.count || 0;
            const pct = rawTotal > 0 ? Math.round((count / rawTotal) * 100) : 0;
            return (
              <div
                key={i}
                className="donut-legend-item"
                style={{ opacity: hovered === null || hovered === i ? 1 : 0.5, cursor: 'pointer' }}
                onMouseEnter={() => setHovered(i)}
                onMouseLeave={() => setHovered(null)}
              >
                <div className="donut-legend-tag">
                  <span className="chart-legend-dot" style={{ background: seg.color }} />
                  <span>{seg.label}</span>
                </div>
                <div className="donut-legend-count">
                  {count} <span style={{ color: 'var(--text-muted)', fontWeight: 400 }}>({pct}%)</span>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

function TelemetryBarChart({ items = [] }) {
  if (!items || items.length === 0) {
    return (
      <div style={{ padding: '24px 16px', textAlign: 'center', color: 'var(--text-muted)', fontSize: 12 }}>
        <Users size={20} style={{ margin: '0 auto 6px', opacity: 0.5, display: 'block' }} />
        No departmental or specialty allocations recorded in this timeframe.
      </div>
    );
  }

  const max = Math.max(1, ...items.map(it => it.count || 0));

  return (
    <div className="telemetry-bar-list" role="region" aria-label="Department specialty distribution">
      {items.map((it, idx) => {
        const count = it.count || 0;
        const pct = Math.round((count / max) * 100);
        return (
          <div key={idx} className="telemetry-bar-item">
            <div className="telemetry-bar-info">
              <span className="telemetry-bar-label">
                <span style={{ width: 8, height: 8, borderRadius: '50%', background: it.color || 'var(--p)' }} />
                {it.label}
              </span>
              <span className="telemetry-bar-val">{count} patients ({pct}%)</span>
            </div>
            <div className="telemetry-track">
              <div
                className="telemetry-fill"
                style={{
                  width: `${pct}%`,
                  background: `linear-gradient(90deg, ${it.color || 'var(--p)'}88 0%, ${it.color || 'var(--p)'} 100%)`
                }}
              />
            </div>
          </div>
        );
      })}
    </div>
  );
}

