function getCustomMedicineLibrary() {
  try {
    const raw = localStorage.getItem('recovera_custom_med_library');
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function saveMedicineToLibrary(medicine) {
  if (!medicine) return false;
  const rawName = typeof medicine === 'string' ? medicine : (medicine.name || medicine.medicine_name || '');
  const cleanName = rawName.trim();
  if (!cleanName || cleanName.length < 2) return false;
  const lowerName = cleanName.toLowerCase();

  const customCatalog = getCustomMedicineLibrary();

  // Deduplicate against static MEDICINE_CATALOG
  const inStatic = MEDICINE_CATALOG.some(m =>
    m.name.toLowerCase() === lowerName ||
    (m.classification && m.classification.toLowerCase() === lowerName)
  );
  if (inStatic) return false;

  // Deduplicate against customCatalog
  const inCustom = customCatalog.some(m =>
    m.name.toLowerCase() === lowerName ||
    (m.classification && m.classification.toLowerCase() === lowerName)
  );
  if (inCustom) return false;

  const newEntry = {
    id: `custom_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
    name: cleanName.charAt(0).toUpperCase() + cleanName.slice(1),
    category: medicine.category || 'Prescription Ingested',
    classification: medicine.classification || medicine.generic || medicine.generic_name || cleanName,
    defaultDose: medicine.dose || medicine.dosage || medicine.defaultDose || '500 mg',
    defaultFreq: medicine.frequency || medicine.defaultFreq || 'twice_daily',
    defaultDays: Number(medicine.days) || medicine.defaultDays || 7,
    defaultFood: medicine.food_relation || medicine.defaultFood || 'after_food',
    common: false,
    isCustom: true
  };

  const updated = [newEntry, ...customCatalog];
  try {
    localStorage.setItem('recovera_custom_med_library', JSON.stringify(updated));
    window.dispatchEvent(new CustomEvent('recovera_med_library_updated', { detail: newEntry }));
  } catch {}
  return true;
}

