                <thead>
                  <tr>
                    <th>Patient</th>
                    <th>Code</th>
                    <th>Phone</th>
                    <th>Reason / Symptoms</th>
                    <th>Status</th>
                    <th>Requested At</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
